  function painterRows(){const pricing=$('#painterWorksheet').dataset.agreementPricing==='true';return Array.from(document.querySelectorAll('#painterWorksheet [data-painter-row]')).map(tr=>{const row={id:tr.dataset.painterRow,linkJobId:tr.dataset.linkJobId||''},items=Array.from(tr.querySelectorAll('[data-job-item]')).map(item=>({description:item.querySelector('[data-job-description]').value,amount:item.querySelector('[data-job-amount]').value}));if(pricing){row.agreementMode=true;if((!row.id&&!row.linkJobId)||tr.dataset.initialPricing==='true')row.agreedWorkItems=items}else row.workItems=items;tr.querySelectorAll('[data-field]').forEach(el=>{row[el.dataset.field]=el.value});return row})}
  function painterState(){return C.setPayday(state,$('#painterPayday').value,ui.employeeId)}
