    document.querySelectorAll('[data-painter-row]').forEach(row=>{if(pricing&&(row.dataset.painterRow||row.dataset.linkJobId)&&row.dataset.initialPricing!=='true')return;const amounts=Array.from(row.querySelectorAll('[data-job-amount]')).map(el=>el.value===''?0:Number(el.value));row.querySelector(pricing?'[data-field="contract"]':'[data-field="weekly"]').value=amounts.every(n=>Number.isFinite(n)&&n>=0)?C.money(amounts.reduce((total,n)=>total+C.cents(n),0)/100)||'':''});
