      tr.querySelector('[data-job-items]').innerHTML=S.jobItemsEditor(O.agreedJobPricingPreview?K.agreementItems(state,ui.employeeId,r.job,state.period.end):items.some(i=>i.description.trim()||Number(i.amount))?items:S.workItems(r),'Linked job',esc,Boolean(O.agreedJobPricingPreview),Boolean(O.agreedJobPricingPreview));
      if(O.agreedJobPricingPreview)tr.querySelector('[data-job-add]')?.remove();
