  function input(label,name,value='',type='text',attrs='',help=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${help?`<small>${help}</small>`:''}</label>`}
  function select(label,name,value,options,attrs=''){return `<label class="field">${label}<select name="${name}" ${attrs}>${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
