  function updateFormHint(){
    if(!editing)return;const form=$('#editorForm'),f=new FormData(form);
    if(RP&&editing.kind==='retention-received'){
      const el=$('#retainedPaydayDestination');editing.destination=null;
      try{const t=RP.target(state,ui.employeeId,f.get('date'));editing.destination=t.period;el.textContent='Destination cutoff: '+range(t.period)+' · Payday: '+dateText(t.period.releaseDate)+'. Regular weekly salary: '+peso(t.source.snapshot.net)+'. Retained payment: '+peso(editing.basis.amount)+'.';}
      catch(error){el.textContent=error.message}return;
    }
    if(editing.kind==='employee'){const contract=form.elements.type.value==='contract',rate=form.elements.rate;rate.disabled=contract;rate.required=!contract;if(contract){if(rate.value)rate.dataset.dailyValue=rate.value;rate.value=''}else if(!rate.value)rate.value=rate.dataset.dailyValue||650}
    if(editing.kind==='complete'){const d=f.get('date');$('#completionHint').textContent=C.validDate(d)?'Retention becomes eligible on '+dateText(C.addDays(d,45))+' (45 calendar days after unit release).':'Select a valid actual release date.';return}
    const el=$('#liveFormHint');if(!el)return;const j=job(f.get('jobId'));if(!j){el.textContent='Choose a unit.';return}
    if(editing.kind==='release'){form.elements.date.min=j.retentionEligibleOn||'';el.textContent='Eligible from '+dateText(j.retentionEligibleOn)+'. Available on this date: '+peso(C.retentionBalance(state,j.id,f.get('date'),editing.id))+'. This becomes a draft entry in the payroll containing its date.'}else el.textContent='Available contract balance: '+peso(C.money(j.contract-C.sum(state.payments.filter(p=>p.jobId===j.id&&p.id!==editing.id),'gross')))+'. Optional withholding plus remaining labor becomes retained salary after unit release. Entries are drafts until the payslip is confirmed released.';
  }
  async function saveEditor(event){
    event.preventDefault();if(editorSaving||O.busy||!editing)return;
    const f=new FormData(event.currentTarget),old=editing.old||{},kind=editing.kind,id=editing.id,photoEditor=employeePhotos;let next=copy(state),row,saved=null,inserted=[],controls=[];
    try{
      if(kind==='unit-release-undo'){
        if(!['owner','edit'].includes(O.access))throw Error('Your payroll access is view-only.');
        if(!f.get('acknowledge'))throw Error('Confirm that this unit release was entered by mistake.');
        if(!discardPainter())throw Error('Save table or undo unsaved changes first.');
        const basis=editing.basis,next=S.undoUnitRelease(state,basis.employeeId,id,basis);
        editorSaving=true;controls=Array.from($('#editorForm').elements).map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);$('#formError').textContent='Undoing unit release…';
        const errors=await commit(next,false,false);if(errors.length)throw Error(errors[0]);
        ui.employeeId=basis.employeeId;ui.type='contract';ui.view='weekly';painterDirty=false;painterCellsDirty=false;
        $('#editorDialog').close();editing=null;render();window.scrollTo(0,0);notify('Unit returned to Ongoing in '+range(basis.period)+'. Payment amounts are unchanged.');return;
      }
      if(kind==='retention-received'){
        if(!f.get('acknowledge'))throw Error('Confirm the employee received the full balance.');
        const date=f.get('date'),basis=editing.basis;
        if(!C.validDate(date)||date<basis.dueOn||date>S.manilaDay())throw Error('Choose a received date from the due date through today.');
        editorSaving=true;controls=Array.from($('#editorForm').elements).map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);$('#formError').textContent='Saving received balance…';
        if(RP&&!editing.destination)throw Error('Review the destination cutoff and save its payroll table first.');
        const period=copy(state.period),loaded=await O.receiveRetention(basis.employeeId,id,date,basis.amount,basis.unitReleasedOn,editing.destination,message=>{$('#formError').textContent=message});
        state={...loaded,period};$('#editorDialog').close();editing=null;render();notify(RP?'Retained payment and payday payslip saved together. Open Past Payslips to review.':'Remaining balance marked as received. Receipt saved; weekly salary unchanged.');return;
      }
      if(kind==='employee-remove')next=C.archiveEmployee(state,id,String(f.get('reason')||''),f.get('date'));
      else if(kind==='complete')next=C.releaseUnit(state,id,f.get('date'));
      else if(kind==='archive-release'){if(!f.get('acknowledge'))throw Error('Confirm that you reviewed the locked copy.');next=A.release(state,id,uid('released'),f.get('date'));saved=next.releasedPainterSlips.find(r=>r.sourceId===id)}
      else if(kind==='finalize'){next=C.saveReleasedPayslip(state,id,uid('15M'),new Date().toISOString());saved=next.payslips[next.payslips.length-1]}
      else if(kind==='confirm-slip'){next=C.confirmPayslip(state,id,f.get('date'),new Date().toISOString());saved=next.payslips.find(s=>s.id===id)}
      else if(kind==='rules')next.rules={lateMode:f.get('lateMode'),hoursPerDay:Number(f.get('hoursPerDay'))};
      else{
        row={...old,id:id||uid(kind)};
        if(kind==='employee'){const type=f.get('type')||old.type;Object.assign(row,{name:String(f.get('name')||'').trim(),position:String(f.get('position')||'').trim(),type,rate:type==='daily'?Number(f.get('rate')):0},C.readEmployeeProfile(Object.fromEntries(f)));row.photos=photoEditor.refs()}
        if(kind==='job')Object.assign(row,{employeeId:f.get('employeeId')||old.employeeId,unit:String(f.get('unit')||'').trim(),year:Number(f.get('year')),plate:String(f.get('plate')||'').trim().toUpperCase(),color:String(f.get('color')||'').trim(),work:String(f.get('work')||'').trim(),contract:old.closed?old.contract:C.money(f.get('contract')),due:old.due||''});
        if(kind==='job')row.invoice=String(f.get('invoice')||'').trim();
        if(kind==='payment')Object.assign(row,{jobId:f.get('jobId'),date:f.get('date'),periodStart:f.get('periodStart'),periodEnd:f.get('periodEnd'),gross:C.money(f.get('gross')),retention:C.money(f.get('retention'))});
        if(kind==='release')Object.assign(row,{jobId:f.get('jobId'),date:f.get('date'),amount:C.money(f.get('amount')),note:String(f.get('note')||'').trim()});
        if(kind==='advance')Object.assign(row,{employeeId:f.get('employeeId'),date:f.get('date'),amount:C.money(f.get('amount')),note:String(f.get('note')||'').trim()});
        if(kind==='plan')Object.assign(row,{jobId:f.get('jobId'),date:f.get('date'),amount:C.money(f.get('amount')),note:String(f.get('note')||'').trim()});
        const index=next[editing.collection].findIndex(r=>r.id===row.id);if(index>=0)next[editing.collection][index]=row;else next[editing.collection].push(row);
        if(kind==='payment'&&editing.planId)next.plans.find(p=>p.id===editing.planId).paymentId=row.id;
      }
      if(kind==='payment'&&!id)next=C.selectWeek(next,row.date);
      if(kind==='employee'){
        const errors=[...C.validateTransition(state,next,today()),...S.validate(next,state),...A.validate(next,state)];if(errors.length)throw Error(errors[0]);
        editorSaving=true;controls=Array.from($('#editorForm').elements).map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);$('#formError').textContent='Saving employee and photos…';
        const records=await D.ensureRecords({employees:[row]},photoEditor.newRecords());inserted=await D.putMany(records);
      }
      await saveNext(next,kind==='finalize'||kind==='archive-release'?'Released payslip saved. Its copy is now fixed.':kind==='employee-remove'?'Employee removed from active list. All records preserved.':'Saved securely online');
      if(kind==='complete'){ui.employeeId=job(id).employeeId;ui.type='contract';ui.view='weekly';render()}
      if(kind==='employee'){ui.employeeId=row.id;ui.type=row.type;render()}
      if(kind==='employee'){const removed=photoEditor.removedIds();try{await D.discardUnreferenced(removed,state)}catch(error){notify('Employee saved. Removed images could not be cleared from browser storage; keep a full backup.')}}
      $('#editorDialog').close();editing=null;if(saved)showPreview([saved]);
    }catch(error){$('#formError').textContent=error.message;try{await D.discardUnreferenced(inserted,state)}catch(cleanupError){/* Preserve files rather than risk deleting another tab's saved photo. */}}
    finally{editorSaving=false;controls.forEach(([el,disabled])=>el.disabled=disabled);if($('#editorDialog').open)$('#editorForm button[type=submit]').disabled=Boolean(employeePhotos?.isBusy())}
  }
  async function showPreview(records,employeeId=null,intent='preview',original=false){
    try{
    records=records.map(s=>{const r=RP&&!original?RP.current(state,s):s;return r.retainedPaydayCopy||original?copy(r):A.enrich(state,r)});
    const printable=records.map(s=>({...s,releaseConfirmation:state.slipReleases.find(r=>r.slipId===s.id)})),sizes=await Promise.all(printable.map(s=>window.PayrollPDF.layout(s)));
    const layout=window.PayrollSlips.render(printable,{paperSizes:sizes.map(s=>s.paper)});previewRecords=records;previewEmployee=employeeId;
    $('#payslipPreview').innerHTML=layout.html;$('#printArea').innerHTML=layout.html;
    $('#slipStatus').textContent=(employeeId?'Draft — not saved':'Saved copy — read-only')+' · '+[layout.halves?layout.halves+' half-bond part(s)':null,layout.fullPages?layout.fullPages+' full-bond part(s)':null].filter(Boolean).join(' / ');
    if(original)$('#slipStatus').textContent='Previous version — reference only; use the latest copy for printing.';
    $('#savePayslip').hidden=!employeeId;$('#savePayslip').disabled=Boolean(employeeId&&savedFor(employeeId));
    $('#savePayslip').textContent=employeeId&&savedFor(employeeId)?'Copy already saved':'Save released payslip';
    $('#printPayslip').textContent='Print';$('#pdfPayslip').textContent='Save as PDF';const single=records.length===1?records[0]:null;$('#releasePayslip').hidden=!single?.snapshot.simpleTest||single.releasedCopy;$('#releasePayslip').disabled=Boolean(single&&A.forWeek(state,single.employeeId,single.period));
    if(original)$('#releasePayslip').hidden=true;
    $('#printIntent').textContent=intent==='pdf'?'Click Save as PDF to download a PDF file.':intent==='print'?'Click Print to open the PDF, then use its printer icon.':'Print and Save as PDF are separate actions. Neither releases the payslip.';
    $('#ownerCorrection').hidden=O.access!=='owner'||records.length!==1||!A.releasedRecords(state).some(r=>r.id===records[0].id);if(!$('#payslipDialog').open)$('#payslipDialog').showModal();
    }catch(error){notify('Payslip preview could not be prepared: '+error.message)}
  }
  function simplePreview(id,intent='preview'){const saved=A.forWeek(state,id,state.period)||S.savedFor(state,id);if(painterDirty||!saved||S.view(state,id).balancesRefreshed)throw Error('Click Save table before Print / PDF so the copy uses the latest balances.');showPreview([saved],null,intent)}
  function releasePainter(id){if(painterDirty||S.view(state,id).balancesRefreshed)throw Error('Save table before releasing so the copy uses the latest balances.');const saved=S.savedFor(state,id);if(!saved)throw Error('Save table before releasing.');if(A.forWeek(state,id,state.period))throw Error('This week already has a locked released copy.');openEditor('archive-release',saved.id)}
  function draftPreview(id){if(employee(id)?.type==='contract'){simplePreview(id);return}showPreview([{id:'DRAFT',snapshot:C.createPayslip(state,id)}],id)}
  function payoutPreview(id,intent){if(employee(id)?.type==='contract'){simplePreview(id,intent);return}const saved=savedFor(id);showPreview(saved?[saved]:[{id:'DRAFT',snapshot:C.createPayslip(state,id)}],saved?null:id,intent)}
  async function exportBackup(){try{if(O.access!=='owner')throw Error('Only the owner can export private employee records.');const data=await D.packBackup(copy(state)),files=await O.getFiles([...state.releasedPainterSlips.map(s=>s.id),...state.slipReleases.map(r=>r.slipId)]);data.releasedPdfFiles=files.filter(Boolean);const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='15M-payroll-private-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('Private backup downloaded. Keep it secure.')}catch(e){notify(e.message)}}
