      const view=event.target.closest('[data-view]');if(view){ui.view=view.dataset.view;if(ui.view==='history'){ui.historyEmployee='';ui.historyQuery=''}if(ui.view==='retention')ui.retentionEmployee='all';render();window.scrollTo(0,0);return}
